@import '@fontsource/instrument-serif/400.css';
@import '@fontsource/instrument-serif/400-italic.css';
@import '@fontsource-variable/ibm-plex-sans/index.css';
@import '@fontsource/ibm-plex-mono/400.css';
@import '@fontsource/ibm-plex-mono/500.css';

/* ------------------------------------------------------------------ system

   Colour is taken from the movement itself: German silver plate, blued screws,
   brass wheels, and the near-black of a bench mat under a loupe. Two
   temperatures, lopsidedly: a warm paper field carries the reading, a cold
   steel field carries the two drawn sections.

   Type: Instrument Serif for the display voice, IBM Plex Sans for reading,
   IBM Plex Mono (tabular) for every number the buyer will compare.
   ---------------------------------------------------------------------- */

:root {
  --paper: #f1ede4;
  --paper-2: #e7e0d1;
  --paper-3: #dcd4c2;
  --ink: #16171b;
  --ink-2: #4a4c53;
  --ink-3: #74757c;

  --steel: #101216;
  --steel-2: #1a1d23;
  --steel-3: #262a32;
  --on-steel: #ded9cd;
  --on-steel-2: #8f9299;

  --silver: #c7c0ac;
  --brass: #c2903f;
  --blued: #4a6ea8;

  --rule: color-mix(in oklch, var(--ink) 16%, transparent);
  --rule-steel: color-mix(in oklch, var(--on-steel) 18%, transparent);

  --sans: 'IBM Plex Sans Variable', system-ui, sans-serif;
  --serif: 'Instrument Serif', Georgia, serif;
  --mono: 'IBM Plex Mono', ui-monospace, monospace;

  /* 1.25 from 16px */
  --t-xs: 0.78rem;
  --t-sm: 0.875rem;
  --t-base: 1rem;
  --t-md: 1.19rem;
  --t-lg: 1.55rem;
  --t-xl: 2.1rem;
  --t-2xl: 3.1rem;
  --t-3xl: clamp(3.4rem, 8vw, 6.6rem);

  --gutter: clamp(1.25rem, 5vw, 5rem);
  --band: clamp(4.5rem, 9vw, 8.5rem);

  --ease-out: cubic-bezier(0.2, 0.8, 0.3, 1);
  --ease-in-out: cubic-bezier(0.6, 0, 0.3, 1);
  --t-fast: 130ms;
  --t-mid: 200ms;
  --t-slow: 340ms;
}

* { box-sizing: border-box; }

html { scroll-behavior: smooth; scroll-padding-top: 5rem; }

body {
  margin: 0;
  background: var(--paper);
  color: var(--ink);
  font-family: var(--sans);
  font-size: var(--t-base);
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
  text-rendering: optimizeLegibility;
}

h1, h2, h3 {
  font-family: var(--serif);
  font-weight: 400;
  letter-spacing: -0.02em;
  line-height: 1.02;
  margin: 0;
}

p { margin: 0; }

.sr-only {
  position: absolute;
  width: 1px; height: 1px;
  padding: 0; margin: -1px;
  overflow: hidden; clip: rect(0 0 0 0);
  white-space: nowrap; border: 0;
}

::selection { background: var(--blued); color: #fff; }

/* ---------------------------------------------------------- ambient layer */

a, button, select, input, label.finish, .slab {
  transition:
    color var(--t-fast) var(--ease-out),
    background-color var(--t-fast) var(--ease-out),
    border-color var(--t-fast) var(--ease-out),
    box-shadow var(--t-mid) var(--ease-out),
    transform var(--t-mid) var(--ease-out),
    opacity var(--t-fast) var(--ease-out);
}

:where(a, button, select, input, label.finish):focus-visible {
  outline: 2px solid var(--blued);
  outline-offset: 3px;
}

[data-reveal] {
  opacity: 0;
  transform: translateY(14px);
  transition: opacity var(--t-slow) var(--ease-out), transform var(--t-slow) var(--ease-out);
}
[data-reveal].is-in { opacity: 1; transform: none; }

@media (prefers-reduced-motion: reduce) {
  html { scroll-behavior: auto; }
  *, ::before, ::after {
    transition-duration: 1ms !important;
    animation-duration: 1ms !important;
    animation-iteration-count: 1 !important;
  }
  [data-reveal] { opacity: 1; transform: none; }
}

/* ------------------------------------------------------------------ shared */

.eyebrow {
  font-family: var(--mono);
  font-size: var(--t-xs);
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--ink-3);
}

.lede {
  font-size: var(--t-md);
  line-height: 1.55;
  color: var(--ink-2);
  max-width: 34ch;
}

.btn {
  display: inline-block;
  font-family: var(--mono);
  font-size: var(--t-sm);
  letter-spacing: 0.06em;
  text-decoration: none;
  padding: 0.85rem 1.4rem;
  border: 1px solid transparent;
}

.btn-primary {
  background: var(--on-steel);
  color: var(--steel);
  border-radius: 2px;
}
.btn-primary:hover { background: #fff; transform: translateY(-2px); }
.btn-primary:active { transform: translateY(0); }

.btn-ghost {
  color: var(--on-steel);
  border-color: var(--rule-steel);
  border-radius: 2px;
}
.btn-ghost:hover { border-color: var(--on-steel); color: #fff; }

/* --------------------------------------------------------------- masthead */

.masthead {
  position: fixed;
  inset: 0 0 auto 0;
  z-index: 20;
  display: flex;
  align-items: baseline;
  gap: 2rem;
  padding: 1rem var(--gutter);
  color: var(--on-steel);
  background: transparent;
  border-bottom: 1px solid transparent;
  transition: background-color var(--t-mid) var(--ease-out),
    border-color var(--t-mid) var(--ease-out), color var(--t-mid) var(--ease-out);
}
.masthead.is-solid {
  background: color-mix(in oklch, var(--steel) 88%, transparent);
  backdrop-filter: blur(8px);
  border-bottom-color: var(--rule-steel);
}

.wordmark {
  font-family: var(--serif);
  font-size: var(--t-md);
  letter-spacing: 0.01em;
  color: inherit;
  text-decoration: none;
  white-space: nowrap;
}
.wordmark span { color: var(--brass); }

.masthead-nav {
  display: flex;
  gap: 1.6rem;
  margin-left: auto;
  font-family: var(--mono);
  font-size: var(--t-xs);
  letter-spacing: 0.08em;
}
.masthead-nav a {
  color: var(--on-steel-2);
  text-decoration: none;
  padding-bottom: 2px;
  border-bottom: 1px solid transparent;
}
.masthead-nav a:hover { color: var(--on-steel); border-bottom-color: var(--brass); }

.masthead-cta {
  font-family: var(--mono);
  font-size: var(--t-xs);
  letter-spacing: 0.08em;
  text-decoration: none;
  color: var(--steel);
  background: var(--on-steel);
  padding: 0.5rem 0.8rem;
  border-radius: 2px;
  white-space: nowrap;
}
.masthead-cta:hover { background: #fff; }
.masthead-cta-note { color: var(--ink-3); }

/* ------------------------------------------------------------------- hero */

.hero,
.power {
  background: var(--steel);
  color: var(--on-steel);
}

.hero {
  display: grid;
  grid-template-columns: minmax(0, 1.05fr) minmax(0, 1fr);
  align-items: center;
  gap: clamp(2rem, 5vw, 5rem);
  padding: clamp(7rem, 12vw, 10rem) var(--gutter) clamp(3rem, 6vw, 5rem);
  position: relative;
}

.hero-house {
  font-family: var(--mono);
  font-size: var(--t-xs);
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: var(--on-steel-2);
}

.hero h1 {
  font-size: var(--t-3xl);
  margin: 0.6rem 0 0;
  color: #f4f1e8;
}
.hero-num {
  font-family: var(--mono);
  font-weight: 400;
  letter-spacing: -0.04em;
  color: var(--brass);
}

.hero-claim {
  margin-top: 1.4rem;
  font-size: var(--t-md);
  line-height: 1.5;
  max-width: 30ch;
  color: var(--on-steel);
}

.hero-facts {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, auto));
  gap: 0 clamp(1.2rem, 3vw, 2.6rem);
  margin: 2.2rem 0 0;
  padding-top: 1.2rem;
  border-top: 1px solid var(--rule-steel);
  justify-content: start;
}
.hero-facts div { display: flex; flex-direction: column-reverse; gap: 0.15rem; }
.hero-facts dt {
  font-family: var(--mono);
  font-size: var(--t-xs);
  letter-spacing: 0.08em;
  color: var(--on-steel-2);
}
.hero-facts dd {
  margin: 0;
  font-family: var(--mono);
  font-size: var(--t-lg);
  font-variant-numeric: tabular-nums;
  color: var(--on-steel);
}

.hero-actions { display: flex; flex-wrap: wrap; gap: 0.75rem; margin-top: 2.4rem; }

.hero-figure {
  position: relative;
  display: flex;
  justify-content: center;
}
.hero-figure .plate {
  width: min(100%, 34rem);
  filter: drop-shadow(0 40px 70px rgba(0, 0, 0, 0.55));
  animation: plate-in 900ms var(--ease-out) both;
}

@keyframes plate-in {
  from { opacity: 0; transform: translateY(18px) scale(0.985); }
  to { opacity: 1; transform: none; }
}

/* ------------------------------------------------------------- schematic */

.plate { display: block; width: 100%; height: auto; overflow: visible; }

.plate-disc { fill: #23262c; }
.plate-grain { stroke: #2c3037; stroke-width: 1; opacity: 0.55; }
.plate-edge { fill: none; stroke: var(--silver); stroke-width: 1.2; opacity: 0.5; }
.plate-edge-inner { fill: none; stroke: var(--silver); stroke-width: 0.6; opacity: 0.22; }

.bridge { fill: #2b2f37; stroke: var(--silver); stroke-width: 0.9; stroke-opacity: 0.45; }

.part { transition: opacity var(--t-slow) var(--ease-out); }
.part-fill { fill: #313640; stroke: var(--silver); stroke-width: 0.7; stroke-opacity: 0.55; }
.part-teeth { fill: none; stroke: var(--silver); stroke-width: 0.9; stroke-opacity: 0.65; }
.arbor { fill: var(--silver); opacity: 0.85; }
.mainspring { fill: none; stroke: var(--silver); stroke-width: 0.8; stroke-opacity: 0.45; }
.hairspring { fill: none; stroke: var(--silver); stroke-width: 0.6; stroke-opacity: 0.4; }
.balance-rim { fill: none; stroke: var(--silver); stroke-width: 3.2; stroke-opacity: 0.8; }
.balance-arm { stroke: var(--silver); stroke-width: 1.4; stroke-opacity: 0.6; }
.inertia-weight { fill: var(--silver); opacity: 0.9; }
.lever { fill: none; stroke: var(--silver); stroke-width: 2; stroke-linecap: round; stroke-opacity: 0.8; }
.hand { stroke: var(--on-steel); stroke-width: 2.2; stroke-linecap: round; }
.hand-hr { stroke-width: 3; }
.jewel { fill: #b8484f; opacity: 0.9; }
.screw { fill: var(--blued); opacity: 0.95; }

.flow-track { fill: none; stroke: var(--brass); stroke-width: 1; stroke-opacity: 0.22; stroke-dasharray: 3 5; }
.flow-pulse {
  fill: none;
  stroke: var(--brass);
  stroke-width: 2.4;
  stroke-linecap: round;
  stroke-dasharray: 26 660;
  stroke-dashoffset: 686;
  opacity: 0;
}
.flow-pulse.is-running {
  opacity: 0.95;
  animation: flow 4.2s linear infinite;
}
@keyframes flow {
  from { stroke-dashoffset: 686; }
  to { stroke-dashoffset: 0; }
}

/* the lit stage: everything else recedes, the stage itself warms up */
.power-figure .part { opacity: 0.42; }
.power-figure .part.is-lit { opacity: 1; }
.part.is-lit .part-teeth,
.part.is-lit .balance-rim,
.part.is-lit .lever,
.part.is-lit .part-fill { stroke: var(--brass); stroke-opacity: 0.95; }
.part.is-lit .part-fill { fill: #3a3323; }
.part.is-lit .arbor,
.part.is-lit .inertia-weight { fill: var(--brass); }
.part.is-lit .mainspring,
.part.is-lit .hairspring { stroke: var(--brass); stroke-opacity: 0.8; }

/* the balance beats at the movement's real rate: 5 semi-oscillations/second */
.balance-spin.is-beating { animation: beat 0.4s var(--ease-in-out) infinite alternate; }
@keyframes beat {
  from { transform: rotate(-26deg); }
  to { transform: rotate(26deg); }
}
.lever.is-beating { animation: lever 0.4s steps(1, end) infinite alternate; transform-origin: 262px 214px; }
@keyframes lever {
  from { transform: rotate(-7deg); }
  to { transform: rotate(7deg); }
}

/* ------------------------------------------------------------- power path */

.power {
  padding: var(--band) var(--gutter) calc(var(--band) + 2rem);
  border-top: 1px solid var(--rule-steel);
}
.power .eyebrow { color: var(--on-steel-2); }
.power .lede { color: var(--on-steel-2); max-width: 46ch; }

.power-intro { max-width: 52rem; }
.power-intro h2 {
  font-size: var(--t-2xl);
  margin: 0.7rem 0 1rem;
  color: #f4f1e8;
  max-width: 18ch;
}

.power-grid {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(0, 1fr);
  gap: clamp(2rem, 5vw, 4.5rem);
  margin-top: clamp(2.5rem, 5vw, 4rem);
}

.power-figure-inner {
  position: sticky;
  top: 6rem;
}
.power-figure .plate { width: min(100%, 32rem); margin-inline: auto; }

.figure-caption {
  display: flex;
  align-items: center;
  gap: 0.6rem;
  flex-wrap: wrap;
  margin-top: 1.2rem;
  font-family: var(--mono);
  font-size: var(--t-xs);
  color: var(--on-steel-2);
  max-width: 40ch;
}
.tick-row { display: inline-flex; gap: 3px; align-items: flex-end; }
.tick {
  width: 2px; height: 10px;
  background: var(--brass);
  opacity: 0.35;
  display: block;
}
.tick.is-beating { animation: tick 0.4s var(--ease-out) infinite; }
@keyframes tick {
  0% { opacity: 1; height: 14px; }
  60%, 100% { opacity: 0.3; height: 10px; }
}

.stages { list-style: none; margin: 0; padding: 0; }

.stage {
  display: grid;
  grid-template-columns: 3.2rem minmax(0, 1fr);
  gap: 1.2rem;
  padding: clamp(2rem, 4vw, 3rem) 0;
  border-top: 1px solid var(--rule-steel);
}
.stage:first-child { border-top: 0; padding-top: 0; }

.stage-rail { position: relative; }
.stage-rail::before {
  content: '';
  position: absolute;
  left: 0.55rem;
  top: 2rem;
  bottom: -3.5rem;
  width: 1px;
  background: var(--rule-steel);
}
.stage:last-child .stage-rail::before { display: none; }

.stage-num {
  display: grid;
  place-items: center;
  width: 1.15rem; height: 1.15rem;
  border: 1px solid var(--rule-steel);
  border-radius: 50%;
  font-family: var(--mono);
  font-size: 0.62rem;
  color: var(--on-steel-2);
  background: var(--steel);
  transition: color var(--t-mid) var(--ease-out), border-color var(--t-mid) var(--ease-out),
    background-color var(--t-mid) var(--ease-out);
}
.stage.is-passed .stage-num { color: var(--brass); border-color: color-mix(in oklch, var(--brass) 60%, transparent); }
.stage.is-active .stage-num { background: var(--brass); color: var(--steel); border-color: var(--brass); }

.stage-body h3 {
  font-size: var(--t-lg);
  color: var(--on-steel-2);
  transition: color var(--t-mid) var(--ease-out);
}
.stage.is-active .stage-body h3 { color: #f4f1e8; }

.stage-figure {
  display: flex;
  align-items: baseline;
  gap: 0.7rem;
  flex-wrap: wrap;
  margin-top: 0.75rem;
}
.stage-figure strong {
  font-family: var(--mono);
  font-weight: 500;
  font-size: clamp(1.7rem, 3vw, 2.4rem);
  font-variant-numeric: tabular-nums;
  letter-spacing: -0.03em;
  color: var(--on-steel-2);
  transition: color var(--t-mid) var(--ease-out);
}
.stage.is-active .stage-figure strong { color: var(--brass); }
.stage-figure span {
  font-family: var(--mono);
  font-size: var(--t-xs);
  letter-spacing: 0.06em;
  color: var(--on-steel-2);
}

.stage-detail {
  margin-top: 0.7rem;
  max-width: 44ch;
  color: var(--on-steel-2);
  opacity: 0.85;
  transition: opacity var(--t-mid) var(--ease-out), color var(--t-mid) var(--ease-out);
}
.stage.is-active .stage-detail { color: var(--on-steel); opacity: 1; }

/* ----------------------------------------------------------------- layers */

.layers {
  padding: var(--band) var(--gutter);
  background:
    linear-gradient(var(--paper), var(--paper)) padding-box;
}
.layers-head h2 { font-size: var(--t-2xl); margin: 0.7rem 0 1rem; max-width: 16ch; }

.layers-grid {
  display: grid;
  grid-template-columns: minmax(0, 1.15fr) minmax(0, 1fr);
  gap: clamp(2rem, 5vw, 4rem);
  align-items: center;
  margin-top: clamp(2.5rem, 5vw, 3.5rem);
}

.stack {
  display: grid;
  grid-template-columns: 4.5rem minmax(0, 1fr);
  gap: 1.2rem;
  align-items: stretch;
}

.stack-scale {
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  justify-content: space-between;
  font-family: var(--mono);
  font-size: var(--t-xs);
  letter-spacing: 0.08em;
  color: var(--ink-3);
  padding: 0.2rem 0;
}
.stack-scale-rule { flex: 1; width: 1px; background: var(--rule); margin: 0.4rem 0.5rem; }

.stack-slabs { display: flex; flex-direction: column; gap: 0.55rem; }

.slab {
  position: relative;
  display: flex;
  align-items: center;
  gap: 1rem;
  height: var(--h);
  min-height: 2.4rem;
  padding: 0 1rem 0 0;
  background: transparent;
  border: 0;
  cursor: pointer;
  text-align: left;
  font: inherit;
  color: inherit;
  transform-origin: left center;
}

.slab-face {
  display: block;
  flex: 1;
  align-self: stretch;
  background:
    repeating-linear-gradient(
      92deg,
      color-mix(in oklch, var(--silver) 82%, #fff) 0 2px,
      color-mix(in oklch, var(--silver) 62%, var(--ink)) 2px 4px
    );
  border: 1px solid color-mix(in oklch, var(--ink) 32%, transparent);
  border-radius: 1px;
  box-shadow: 0 1px 0 rgba(255, 255, 255, 0.5) inset, 0 6px 14px -10px rgba(0, 0, 0, 0.7);
  transition: transform var(--t-mid) var(--ease-out), box-shadow var(--t-mid) var(--ease-out),
    background-color var(--t-mid) var(--ease-out), border-color var(--t-mid) var(--ease-out);
}

.slab:hover .slab-face { transform: translateX(10px); }
.slab.is-open .slab-face {
  transform: translateX(22px);
  border-color: var(--blued);
  box-shadow: 0 1px 0 rgba(255, 255, 255, 0.6) inset, 0 14px 24px -14px rgba(0, 0, 0, 0.75);
}

.slab-label {
  display: flex;
  flex-direction: column;
  min-width: 11rem;
  font-family: var(--mono);
  font-size: var(--t-xs);
  letter-spacing: 0.04em;
  color: var(--ink-3);
}
.slab-name { color: var(--ink-2); }
.slab.is-open .slab-name { color: var(--ink); }
.slab-mm {
  font-variant-numeric: tabular-nums;
  font-size: var(--t-sm);
  color: var(--ink);
}
.slab.is-open .slab-mm { color: var(--blued); }

.layer-notes { display: flex; flex-direction: column; gap: 1px; border-top: 1px solid var(--rule); }
.layer-note {
  display: grid;
  gap: 0.3rem;
  padding: 1rem 0;
  border-bottom: 1px solid var(--rule);
  opacity: 0.42;
  transition: opacity var(--t-mid) var(--ease-out);
}
.layer-note.is-open { opacity: 1; }
.layer-note-name {
  font-family: var(--mono);
  font-size: var(--t-xs);
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--ink);
}
.layer-note-mm { color: var(--blued); }
.layer-note-text { color: var(--ink-2); max-width: 44ch; }

/* ------------------------------------------------------------------- spec */

.spec {
  padding: var(--band) var(--gutter);
  background: var(--paper-2);
  border-top: 1px solid var(--rule);
  display: grid;
  grid-template-columns: minmax(0, 0.8fr) minmax(0, 1.2fr);
  gap: clamp(2rem, 5vw, 4rem);
  align-items: start;
}
.spec-head h2 { font-size: var(--t-xl); margin-top: 0.7rem; max-width: 12ch; }

.spec-list { margin: 0; }
.spec-row {
  display: flex;
  align-items: baseline;
  gap: 1rem;
  padding: 0.7rem 0;
  border-bottom: 1px solid var(--rule);
  transition: background-color var(--t-fast) var(--ease-out);
}
.spec-row:first-child { border-top: 1px solid var(--ink); }
.spec-row:hover { background: color-mix(in oklch, var(--paper) 70%, transparent); }
.spec-row dt {
  font-family: var(--mono);
  font-size: var(--t-xs);
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--ink-3);
  white-space: nowrap;
}
.spec-row dd {
  margin: 0 0 0 auto;
  font-family: var(--mono);
  font-size: var(--t-md);
  font-variant-numeric: tabular-nums;
  text-align: right;
}

/* --------------------------------------------------------------- workshop */

.workshop {
  padding: var(--band) var(--gutter);
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(0, 1fr);
  gap: clamp(2rem, 5vw, 4.5rem);
  align-items: start;
  border-top: 1px solid var(--rule);
}

.run-number {
  display: block;
  font-family: var(--mono);
  font-weight: 400;
  font-size: clamp(6rem, 17vw, 13rem);
  line-height: 0.82;
  letter-spacing: -0.06em;
  color: var(--ink);
  margin-top: 1rem;
}
.run-line {
  margin-top: 1.4rem;
  font-family: var(--serif);
  font-size: var(--t-lg);
  line-height: 1.25;
  max-width: 24ch;
}

.workshop-facts { list-style: none; margin: 0; padding: 0; }
.workshop-facts li {
  padding: 1.1rem 0 1.1rem 2.2rem;
  border-top: 1px solid var(--rule);
  color: var(--ink-2);
  max-width: 52ch;
  position: relative;
}
.workshop-facts li::before {
  content: '';
  position: absolute;
  left: 0;
  top: 1.65rem;
  width: 1rem;
  height: 1px;
  background: var(--brass);
}
.workshop-facts li:last-child { border-bottom: 1px solid var(--rule); }

/* --------------------------------------------------------------- finishes */

.reserve {
  padding: var(--band) var(--gutter) calc(var(--band) + 1rem);
  background: var(--paper-2);
  border-top: 1px solid var(--rule);
}
.reserve-head h2 { font-size: var(--t-2xl); margin: 0.7rem 0 1rem; max-width: 20ch; }

.finishes {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 1px;
  margin-top: clamp(2.5rem, 5vw, 3.5rem);
  background: var(--rule);
  border: 1px solid var(--rule);
}

.finish {
  display: grid;
  grid-template-rows: auto auto auto 1fr auto auto;
  gap: 0.55rem;
  padding: 1.6rem 1.4rem 1.2rem;
  background: var(--paper);
  cursor: pointer;
  position: relative;
}
.finish input { position: absolute; opacity: 0; pointer-events: none; }
.finish:hover { background: #f7f4ec; }
.finish.is-selected { background: var(--steel); color: var(--on-steel); }
.finish:has(input:focus-visible) { outline: 2px solid var(--blued); outline-offset: -2px; }

.finish-swatch {
  width: 100%;
  height: 4.5rem;
  border-radius: 1px;
  border: 1px solid color-mix(in oklch, var(--ink) 25%, transparent);
}
[data-swatch='frosted'] {
  background:
    radial-gradient(circle at 30% 30%, #efe9dc, #cfc7b2 70%),
    #cfc7b2;
}
[data-swatch='skeleton'] {
  background:
    repeating-linear-gradient(115deg, #cfc7b2 0 14px, #6d6552 14px 20px, #cfc7b2 20px 30px);
}
[data-swatch='black'] {
  background: linear-gradient(115deg, #0c0d10 0 42%, #6f7683 52%, #0c0d10 62%, #2a2e35 100%);
}

.finish-name {
  font-family: var(--serif);
  font-size: var(--t-lg);
  line-height: 1.1;
}
.finish-price {
  font-family: var(--mono);
  font-size: var(--t-md);
  font-variant-numeric: tabular-nums;
  color: var(--brass);
}
.finish-desc { font-size: var(--t-sm); color: var(--ink-2); }
.finish.is-selected .finish-desc { color: var(--on-steel-2); }

.finish-meta {
  display: grid;
  gap: 0.5rem;
  padding-top: 0.9rem;
  border-top: 1px solid var(--rule);
  font-family: var(--mono);
  font-size: var(--t-xs);
  letter-spacing: 0.04em;
  color: var(--ink-2);
}
.finish.is-selected .finish-meta { border-top-color: var(--rule-steel); color: var(--on-steel-2); }
.finish-lead { color: var(--ink); }
.finish.is-selected .finish-lead { color: var(--on-steel); }
.finish-remaining { display: grid; gap: 0.35rem; }
.finish-remaining-bar {
  display: block;
  height: 3px;
  background: color-mix(in oklch, var(--ink) 14%, transparent);
}
.finish-remaining-bar span { display: block; height: 100%; background: var(--brass); }

.finish-choose {
  margin-top: 0.4rem;
  font-family: var(--mono);
  font-size: var(--t-xs);
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--ink-3);
}
.finish:hover .finish-choose { color: var(--blued); }
.finish.is-selected .finish-choose { color: var(--brass); }

/* -------------------------------------------------------------- the form */

.reserve-panel {
  margin-top: clamp(2rem, 4vw, 3rem);
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  max-width: 62rem;
}

.reserve-panel form {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 1.1rem 1.5rem;
  align-items: end;
  padding: clamp(1.5rem, 3vw, 2.2rem);
  background: var(--paper);
  border: 1px solid var(--ink);
}
.form-title {
  grid-column: 1 / -1;
  font-family: var(--serif);
  font-size: var(--t-xl);
}
.field { display: grid; gap: 0.4rem; }
.field label {
  font-family: var(--mono);
  font-size: var(--t-xs);
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--ink-3);
}
.field input,
.field select {
  font-family: var(--sans);
  font-size: var(--t-base);
  padding: 0.7rem 0.8rem;
  background: transparent;
  border: 1px solid var(--rule);
  border-radius: 2px;
  color: var(--ink);
  width: 100%;
}
.field input:hover,
.field select:hover { border-color: var(--ink-3); }
.field input:focus,
.field select:focus { border-color: var(--blued); outline: none; box-shadow: 0 0 0 3px color-mix(in oklch, var(--blued) 22%, transparent); }

.form-echo {
  grid-column: 1 / -1;
  font-family: var(--mono);
  font-size: var(--t-xs);
  letter-spacing: 0.06em;
  color: var(--blued);
}
.form-error {
  grid-column: 1 / -1;
  font-size: var(--t-sm);
  color: #9a3b32;
}

.reserve-panel button {
  grid-column: 1 / -1;
  justify-self: start;
  font-family: var(--mono);
  font-size: var(--t-sm);
  letter-spacing: 0.08em;
  padding: 0.9rem 1.6rem;
  background: var(--ink);
  color: var(--paper);
  border: 1px solid var(--ink);
  border-radius: 2px;
  cursor: pointer;
}
.reserve-panel button:hover { background: var(--blued); border-color: var(--blued); transform: translateY(-2px); }
.reserve-panel button:active { transform: translateY(0); }

.reserve-terms {
  grid-column: 1 / -1;
  font-size: var(--t-sm);
  color: var(--ink-2);
  max-width: 56ch;
}

.confirmation {
  padding: clamp(1.5rem, 3vw, 2.2rem);
  background: var(--steel);
  color: var(--on-steel);
  border: 1px solid var(--steel);
  display: grid;
  gap: 1.1rem;
}
.confirmation-mark {
  font-family: var(--mono);
  font-size: var(--t-xs);
  letter-spacing: 0.2em;
  text-transform: uppercase;
  color: var(--brass);
}
.confirmation-body { font-family: var(--serif); font-size: var(--t-xl); line-height: 1.18; max-width: 30ch; color: #f4f1e8; }
.confirmation-record {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 1rem;
  margin: 0;
  padding-top: 1.1rem;
  border-top: 1px solid var(--rule-steel);
}
.confirmation-record dt {
  font-family: var(--mono);
  font-size: var(--t-xs);
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--on-steel-2);
}
.confirmation-record dd {
  margin: 0.3rem 0 0;
  font-family: var(--mono);
  font-size: var(--t-md);
  font-variant-numeric: tabular-nums;
  color: var(--on-steel);
}
.confirmation .reserve-terms { color: var(--on-steel-2); }

/* ------------------------------------------------------------------ foot */

.foot {
  background: var(--steel);
  color: var(--on-steel-2);
  padding: clamp(2.5rem, 5vw, 4rem) var(--gutter);
  display: flex;
  flex-wrap: wrap;
  gap: 1rem 2.5rem;
  align-items: baseline;
  font-family: var(--mono);
  font-size: var(--t-xs);
  letter-spacing: 0.06em;
}
.foot-links { display: flex; gap: 1.5rem; flex-wrap: wrap; }
.foot a { color: var(--on-steel-2); text-decoration: none; border-bottom: 1px solid transparent; padding-bottom: 2px; }
.foot a:hover { color: var(--on-steel); border-bottom-color: var(--brass); }
.foot-mail { margin-left: auto; }

/* ---------------------------------------------------------------- tablet */

@media (max-width: 1000px) {
  .hero { grid-template-columns: minmax(0, 1fr); }
  .hero-figure { order: -1; }
  .hero-figure .plate { width: min(72%, 24rem); }
  .power-grid,
  .layers-grid,
  .spec,
  .workshop { grid-template-columns: minmax(0, 1fr); }
  .finishes { grid-template-columns: minmax(0, 1fr); }
  .reserve-panel form { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  .masthead-nav { display: none; }
}

/* ---------------------------------------------------------------- mobile */

@media (max-width: 640px) {
  :root { --t-2xl: 2.3rem; --t-xl: 1.7rem; --t-lg: 1.35rem; }

  .masthead { padding: 0.7rem var(--gutter); gap: 1rem; }
  .masthead-cta-note { display: none; }

  .hero { padding-top: 5.5rem; gap: 2rem; }
  .hero-facts { grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 1rem 1.5rem; }
  .hero-actions .btn { flex: 1; text-align: center; }

  /* the drawing stays in view at the top while the stages scroll under it */
  .power-figure-inner {
    position: sticky;
    top: 3.4rem;
    z-index: 2;
    background: color-mix(in oklch, var(--steel) 94%, transparent);
    backdrop-filter: blur(6px);
    padding-bottom: 0.6rem;
    margin-inline: calc(var(--gutter) * -1);
    padding-inline: var(--gutter);
    border-bottom: 1px solid var(--rule-steel);
  }
  .power-figure .plate { width: min(52%, 13rem); }
  .figure-caption { font-size: 0.7rem; margin-top: 0.5rem; max-width: none; }

  .stage { grid-template-columns: 2.2rem minmax(0, 1fr); gap: 0.8rem; padding: 1.8rem 0; }
  .stage-rail::before { left: 0.55rem; }

  .stack { grid-template-columns: 2.6rem minmax(0, 1fr); gap: 0.7rem; }
  .slab { padding-right: 0; gap: 0.7rem; }
  .slab-label { min-width: 8.2rem; }
  .layers-grid { gap: 1.8rem; }

  .spec-row { flex-wrap: nowrap; }
  .spec-row dd { font-size: var(--t-base); }

  .reserve-panel form { grid-template-columns: minmax(0, 1fr); }
  .confirmation-record { grid-template-columns: minmax(0, 1fr); gap: 0.8rem; }
  .confirmation-record div { display: flex; justify-content: space-between; align-items: baseline; gap: 1rem; }
  .confirmation-record dd { margin-top: 0; }

  .foot { flex-direction: column; gap: 1.2rem; }
  .foot-mail { margin-left: 0; }
}

